'\n    Test adjacency_calc function, which calculates indices of adjacent voxels\n    '
cutoff = 1.99
for img_shape in [(50, 50), (50, 50, 5)]:
    mask = None
    adj = adjacency_calc(img_shape, mask=mask, cutoff=cutoff)
    adj[0].sort()
    if len(img_shape) == 2:
        npt.assert_equal(adj[0], [0, 1, 50, 51])
    if len(img_shape) == 3:
        npt.assert_equal(adj[0], [0, 1, 5, 6, 250, 251, 255, 256])
    mask = np.zeros(img_shape, dtype=int)
    if len(img_shape) == 2:
        mask[10:40, 20:30] = 1
    if len(img_shape) == 3:
        mask[10:40, 20:30, :] = 1
    adj = adjacency_calc(img_shape, mask=mask, cutoff=cutoff)
    if len(img_shape) == 2:
        npt.assert_equal(adj[0], [0, 1, 10, 11])
    if len(img_shape) == 3:
        npt.assert_equal(adj[0], [0, 1, 5, 6, 50, 51, 55, 56])
    npt.assert_equal(len(adj), mask.sum())

'Testing symmetry of the elements of the KT\n\n    As an 4th order tensor, KT has 81 elements. However, due to diffusion\n    symmetry the KT is fully characterized by 15 independent elements. This\n    test checks for this property.\n    '
mevals = np.array([[0.00099, 0, 0], [0.00226, 0.00087, 0.00087], [0.00099, 0, 0], [0.00226, 0.00087, 0.00087]])
angles = [(80, 10), (80, 10), (20, 30), (20, 30)]
fie = 0.49
frac = [fie * 50, (1 - fie) * 50, fie * 50, (1 - fie) * 50]
sticks = _check_directions(angles)
mD = np.zeros((len(frac), 3, 3))
for i in range(len(frac)):
    R = all_tensor_evecs(sticks[i])
    mD[i] = np.dot(np.dot(R, np.diag(mevals[i])), R.T)
D = np.zeros((3, 3))
for i in range(len(frac)):
    D = D + frac[i] * mD[i]
MD = (D[0][0] + D[1][1] + D[2][2]) / 3
kt_ref = {1: kurtosis_element(mD, frac, 0, 0, 0, 0), 16: kurtosis_element(mD, frac, 1, 1, 1, 1), 81: kurtosis_element(mD, frac, 2, 2, 2, 2), 2: kurtosis_element(mD, frac, 0, 0, 0, 1), 3: kurtosis_element(mD, frac, 0, 0, 0, 2), 8: kurtosis_element(mD, frac, 0, 1, 1, 1), 24: kurtosis_element(mD, frac, 1, 1, 1, 2), 27: kurtosis_element(mD, frac, 0, 2, 2, 2), 54: kurtosis_element(mD, frac, 1, 2, 2, 2), 4: kurtosis_element(mD, frac, 0, 0, 1, 1), 9: kurtosis_element(mD, frac, 0, 0, 2, 2), 36: kurtosis_element(mD, frac, 1, 1, 2, 2), 6: kurtosis_element(mD, frac, 0, 0, 1, 2), 12: kurtosis_element(mD, frac, 0, 1, 1, 2), 18: kurtosis_element(mD, frac, 0, 1, 2, 2)}
xyz = [0, 1, 2]
for i in xyz:
    for j in xyz:
        for k in xyz:
            for ell in xyz:
                key = (i + 1) * (j + 1) * (k + 1) * (ell + 1)
                assert_almost_equal(kurtosis_element(mD, frac, i, k, j, ell), kt_ref[key])
                assert_almost_equal(kurtosis_element(mD, frac, i, k, j, ell), kurtosis_element(mD, frac, i, k, j, ell, DT=D, MD=MD))

class VectorOfEndpointsFeature(dipysfeature.Feature):

    def __init__(self):
        super().__init__(False)

    def infer_shape(self, streamline):
        return (1, streamline.shape[1])

    def extract(self, streamline):
        return streamline[[-1]] - streamline[[0]]
feature_types = [dipysfeature.VectorOfEndpointsFeature(), VectorOfEndpointsFeature()]
for feature in feature_types:
    for s in [s1, s2, s3, s4]:
        assert_equal(feature.infer_shape(s), (1, s.shape[1]))
        features = feature.extract(s)
        assert_equal(features.shape, (1, s.shape[1]))
        assert_array_almost_equal(features, s[[-1]] - s[[0]])
    assert_false(feature.is_order_invariant)
    for s in [s1, s2, s3, s4]:
        features = feature.extract(s)
        features_flip = feature.extract(s[::-1])
        assert_array_almost_equal(features, -features_flip)

class CenterOfMass64bit(dipysfeature.Feature):

    def infer_shape(self, streamline):
        return streamline.shape[1]

    def extract(self, streamline):
        return np.mean(streamline.astype(np.float64), axis=0)
nb_streamlines = 100
feature_shape = (1, 3)
feature = CenterOfMass64bit()
nb_points = rng.integers(20, 30, size=(nb_streamlines,)) * 3
streamlines = [np.arange(nb).reshape((-1, 3)).astype(np.float32) for nb in nb_points]
features = extract(feature, streamlines)
assert_equal(len(features), len(streamlines))
assert_equal(features[0].shape, feature_shape)

class ArcLengthFeature(dipysfeature.Feature):

    def infer_shape(self, streamline):
        return 1

    def extract(self, streamline):
        square_norms = np.sum((streamline[1:] - streamline[:-1]) ** 2)
        return np.sum(np.sqrt(square_norms))
feature_shape = (1, 1)
feature = ArcLengthFeature()
features = extract(feature, streamlines)
assert_equal(len(features), len(streamlines))
assert_equal(features[0].shape, feature_shape)
for s in streamlines:
    s.setflags(write=False)

